from functools import lru_cache
G=['.XX.XX.','XXXXXX.','.XX.X..','..XXX..']
cells={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='X'}
# admissible tiles: 2x2 square and L3 forms; tile supports clipped grid
pieces=[]
for r in range(4):
 for c in range(7):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=cells: pieces.append((sq,('S',None)))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   sh={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
   if sh<=cells: pieces.append((sh,('L',miss)))
by={x:[] for x in cells}
for i,(sh,t) in enumerate(pieces):
 for x in sh: by[x].append(i)
sol=[]
def rec(left, selected):
 if not left:
  sol.append(selected); return
 x=min(left,key=lambda z:sum(pieces[i][0]<=left for i in by[z]))
 for i in by[x]:
  sh,t=pieces[i]
  if sh<=left: rec(left-sh,selected+[i])
rec(cells,[])
print('cells',len(cells),'tilings',len(sol))
for k,s in enumerate(sol[:30]):
 print('tiling',k,[(pieces[i][1],sorted(pieces[i][0])) for i in s])

